async function clock(){const a=performance.now(),r=await api('clock'),b=performance.now();offsetMs=r.monotonic_ns/1e6-(a+b)/2;uncertaintyMs=(b-a)/2;}
async function startAudio(clockReady=Promise.resolve()){if(pendingReference)throw new Error('Recover the previous microphone reference in Settings before starting another take.');audioActive=false;audioStopped=false;browserBlob=null;if(!$('referenceAudio').checked)return;if(native)await bridge('audioStart',{followSpeech:activeSession?.collection?.plan.task==='reading'&&$('readerFollow').value==='voice'});else{await clockReady;if(!browserAudio)throw new Error('Enable reference audio again.');const chunks=[];browserRecorder=new MediaRecorder(browserAudio);browserRecorder.ondataavailable=e=>{if(e.data.size)chunks.push(e.data);};browserBlob=new Promise(resolve=>browserRecorder.onstop=()=>resolve(new Blob(chunks,{type:browserRecorder.mimeType})));browserAudioStart=(performance.now()+offsetMs)*1e6;browserRecorder.start();}audioActive=true;}
