async function recoverReferenceAudio(quiet=false){
 if(busy)throw new Error('Finish the current capture first.');
 const button=$('recoverAudio');button.disabled=true;
 try{
  if(pendingReference)await attachAudio(pendingReference.sid,pendingReference.tid);
  const result=native?await bridge('audioRecover'):{recovered:1,pending:0};
  const message=result.pending?`${result.pending} audio reference(s) saved locally, waiting to attach. ${result.message||''}`:result.recovered?`Recovered ${result.recovered} audio reference(s).`:'No audio references awaiting recovery.';
  $('audioRecoveryState').textContent=message;
  if(!quiet||result.pending||result.recovered)notice(message,!!result.pending);
  if(result.recovered){await refreshLibrary();if(selected&&stage==='replay')await openTake(selected.session_id,selected.id);}
 }finally{button.disabled=false;}
}
