async function finishTake(){releaseRequested=true;if(!activeRecord)return;await event('key_up');const r=await api('record/'+activeRecord.id);if(!cued||r.status==='arming'){await api('record/'+activeRecord.id+'/cancel','POST');return;}if(r.status==='recording'){const elapsed=(performance.now()+offsetMs)-r.server_monotonic_start_ns/1e6;const minimum=state.source==='dca1000'?510:Math.max(510,8000/(state.profile?.frame_hz||20));if(minimum-elapsed>700)$('recordingState').textContent='Finishing minimum radar window…';await sleep(Math.max(0,minimum-elapsed));if(activeRecord)await api('record/'+activeRecord.id+'/stop','POST');}}
async function toggleRecording(){if(activeRecord){await finishTake();return;}if(!canStartCapture())return;busy=true;captureOutcome();$('recordingState').textContent='Preparing…';$('recordingState').classList.remove('active');$('recordButton').textContent='Preparing…';$('recordButton').disabled=true;$('readerFollow').disabled=true;releaseRequested=false;cued=false;const step=currentStep(),limit=captureLimit(step);let rid,saved=false,audioWarning='';try{updateCaptureFeedback('arming',0,limit);overlay('Arming…',step.prompt_text,true);setBusyControls(true);if(activeSession.collection.plan.task==='reading'&&$('readerFollow').value==='voice'&&(!$('referenceAudio').checked||!native))throw new Error('Voice following needs reference audio and the installed app.');if(state.session?.id!==activeSession.id)await api('sessions/'+activeSession.id+'/resume','POST');const clockReady=clock(),prepared=await Promise.allSettled([startAudio(clockReady),clockReady]);const failed=prepared.find(r=>r.status==='rejected');if(failed)throw failed.reason;const rec=await api('collect','POST',{step_id:step.step_id,reference_expected:$('referenceAudio').checked,capture_method:activeSession.collection.plan.task==='reading'?'reader':hold?'hold':'button',reader_follow:activeSession.collection.plan.task==='reading'?$('readerFollow').value:null,reader_wpm:activeSession.collection.plan.task==='reading'?Number($('pace').value):null});activeRecord=rec;rid=rec.id;await event('key_down');$('cancelButton').hidden=false;if(releaseRequested&&!timedTake(step))await finishTake();while(true){const r=await api('record/'+rid);if(r.status==='recording'&&!cued){cued=true;readerStarted=performance.now();readerLastTick=readerStarted;if(native){await bridge('cue');await event('cue_finished');}else await event('cue_shown');if(releaseRequested&&!timedTake(step))await finishTake();}const label={arming:'Arming sensor…',recording:'Recording',processing:'Saving…',complete:'Saving…',cancelling:'Cancelling…'}[r.status]||r.status;$('recordingState').textContent=label;$('recordingState').classList.toggle('active',r.status==='recording');$('recordButton').textContent=r.status==='recording'?(timedTake(step)?'Recording · stops automatically':activeSession.collection.plan.task==='reading'?'Finish passage':'Release to finish'):label;$('recordButton').disabled=timedTake(step)||!['recording','arming'].includes(r.status);const elapsed=r.status==='recording'?Math.max(0,((performance.now()+offsetMs)*1e6-r.server_monotonic_start_ns)/1e9):captureElapsed;updateCaptureFeedback(r.status,elapsed,limit);if(!['complete','failed','cancelled'].includes(r.status))overlay(label,step.prompt_text,true,elapsed,timedTake(step)||!controlTake(step)?limit:0);if(r.status==='processing')await stopAudio();if(['complete','failed','cancelled'].includes(r.status)){await stopAudio();if(r.status==='complete'){try{audioWarning=await attachAudio(r.session_id,r.trial.id);}catch(e){audioWarning='Radar saved · microphone reference retained. Recover audio in Settings before recording again. '+e.message;}trials=await api('sessions/'+activeSession.id+'/trials');stepOverride=null;await refreshLibrary();saved=true;overlay('Saved',step.prompt_text,false);showSavedToast(trials.at(-1),audioWarning);}else{await discardAudio();if(r.status==='failed')throw new Error(r.error||'Capture failed.');notice('Take cancelled.');}break;}await sleep(120);}}catch(e){if(rid)await api('record/'+rid+'/cancel','POST').catch(()=>{});if(!pendingReference)await discardAudio();captureOutcome(e.message,{label:'Open session',run:()=>selectedDefinition?openCollection(selectedDefinition.id):sceneHome()},true);}finally{activeRecord=null;busy=false;hold=false;$('readerFollow').disabled=false;setBusyControls(false);if(!saved)overlay('Idle');renderPrompt();if(saved)try{await afterCapture();}catch(e){showSavedToast(trials.at(-1),'Take saved · quality check unavailable: '+e.message);}}}
