async function audioWaveform(url,id){waveform=[];waveformError='';let ctx;try{const r=await fetch(url);if(!r.ok)throw new Error('Reference audio is unavailable.');const buffer=await r.arrayBuffer();ctx=new AudioContext();const decoded=await ctx.decodeAudioData(buffer),values=decoded.getChannelData(0),out=[],bins=1500;for(let i=0;i<bins;i++){let max=0;const a=Math.floor(i*values.length/bins),b=Math.floor((i+1)*values.length/bins);for(let j=a;j<b;j++)max=Math.max(max,Math.abs(values[j]));out.push(max);}if(selected?.id===id){waveform=out;drawTimeline();}}catch(e){if(selected?.id===id){waveformError='Waveform unavailable · '+e.message;trackCache={};drawTimeline();notice(waveformError,true);}}finally{if(ctx)await ctx.close();}}

async function openTake(sid,tid){if(busy)throw new Error('Finish the current recording before replay.');const request=++takeRequest;await saveIfDirty();if(request!==takeRequest)return;pause();const take=await api('sessions/'+sid+'/trials/'+tid);if(request!==takeRequest)return;if(!take)throw new Error('Recording not found');Learning.clearReturn();recordReviewOrigin=null;reviewCollectionId=null;$('reviewQueue').hidden=true;$('keepTakeLabel').textContent='Verify & keep';selected=take;selectedDefinition=sessions.find(s=>s.id===sid)?.collection?.definition||null;replay=null;frame=null;frameSeq++;selectionSeq++;audio.removeAttribute('src');audio.load();waveformError='';$('qualitySummary').hidden=true;$('recordingDetails').hidden=true;$('detailsButton').setAttribute('aria-expanded','false');time=0;zoom=1;viewStart=0;words=structuredClone(take.words||[]);wordIndex=words.length?0:-1;dirty=false;revision=take.annotation_revision||0;undo=[];waveform=[];showTab('capture');setStage('replay');const order=recordings.filter(t=>t.session_id===sid).sort((a,b)=>a.created_ns-b.created_ns).findIndex(t=>t.id===tid);$('recordingTitle').textContent=order>=0?`Take ${order+1}`:'Recording';$('reviewTimingHint').textContent=['rest','negative'].includes(take.articulation)?take.prompt_text:take.articulation==='silent'?'Silent word timing is reviewed independently of the aloud reference.':'Confirm the text below. Word timing can be added from audio or placed manually.';$('recordingBadge').textContent=`${take.articulation||'silent'} · ${take.review_status||'legacy'}${take.synthetic?' · SIMULATOR':''}`;$('confirmedText').value=take.confirmed_text||(take.target_text??(!take.collection_protocol?take.label:''));if(!words.length&&$('confirmedText').value)words=$('confirmedText').value.trim().split(/\s+/).map(text=>({text,start_s:null,end_s:null,source:'manual'}));$('trimStart').value=take.utterance_start_s||0;$('trimEnd').value=take.utterance_end_s||take.duration_s;$('reviewNotes').value=take.notes||'';$('reviewState').textContent=take.review_status||'Legacy recording';$('returnStudio').hidden=true;$('sceneBreadcrumb').textContent=sessions.find(s=>s.id===sid)?.collection?.definition?.name||sessions.find(s=>s.id===sid)?.name||'Recording';renderUnplaced();updateWordLabel();await loadReplay();if(request!==takeRequest||selected?.id!==tid||!replay)return;const session=sessions.find(s=>s.id===sid),conditions=take.capture_conditions||session?.collection||{};const info={Person:session?.subject||'Unknown',Distance:conditions.distance_cm?conditions.distance_cm+' cm':'Unknown',Location:conditions.location||'Unknown',Enclosure:conditions.enclosure||'Unknown',Mount:conditions.mount||'Unknown',Orientation:`Yaw ${conditions.yaw_deg??'?'}° · pitch ${conditions.pitch_deg??'?'}° · roll ${conditions.roll_deg??'?'}°`,Firmware:session?.device_info?.sdk_version||'Not recorded',Profile:session?.profile?.sha256||'Unknown',Quality:`${take.frames} samples · ${take.frame_gaps} missing · ${take.measured_hz.toFixed(1)} samples/s`,Timing:take.timing_note||'Host-clock estimates',Script:take.script_sha256||session?.collection?.plan.deck_name||'Legacy'};$('recordingDetails').innerHTML=Object.entries(info).map(([k,v])=>`<div><span>${esc(k)}</span><strong>${esc(v)}</strong></div>`).join('');const first=Number(replay.first_timestamp_ns),audioHost=take.media?.native_audio_timing?.first_sample_host_ns??take.media?.browser_start_server_ns;audioOffset=take.audio_offset_s??(audioHost?(Number(audioHost)-first)/1e9:0);$('audioOffset').value=audioOffset.toFixed(4);$('suggestWords').disabled=!native||!take.media||take.articulation==='silent';audio.pause();audio.removeAttribute('src');audio.load();if(take.media){const url=`/api/sessions/${sid}/trials/${tid}/media`;audio.src=url;audio.load();audioWaveform(url,take.id);}$('timelineNote').textContent=take.media?'Audio + text · shared radar time · host alignment estimate':'Text + radar · no reference audio';renderLibrary();drawTimeline();}
act('detailsButton',()=>{$('recordingDetails').hidden=!$('recordingDetails').hidden;$('detailsButton').setAttribute('aria-expanded',String(!$('recordingDetails').hidden));});
async function applyAlignment(incoming,timebase='radar',source='alignment_import'){if(!selected||!replay)return;const converted=incoming.map(w=>({text:String(w.text??w.word??''),start_s:Number(w.start_s??w.start)+(timebase==='audio'?audioOffset:0),end_s:Number(w.end_s??w.end)+(timebase==='audio'?audioOffset:0),source}));if(converted.some(w=>!w.text||!Number.isFinite(w.start_s)||!Number.isFinite(w.end_s)||w.start_s<0||w.end_s>replay.duration_s||w.end_s<=w.start_s))throw new Error('Some word times lie outside the radar recording. Check the audio offset and alignment.');validWords(converted);const existing=$('confirmedText').value.trim().split(/\s+/).filter(w=>/[\p{L}\p{N}]/u.test(w)),normalize=s=>s.toLowerCase().replace(/[^\p{L}\p{N}']/gu,'');if(existing.length){if(existing.length!==converted.length||existing.some((w,i)=>normalize(w)!==normalize(converted[i].text)))throw new Error('The alignment text differs from your reviewed text. Correct the transcript or import an alignment made from that exact text.');converted.forEach((w,i)=>w.text=existing[i]);}pushUndo();words=converted;$('confirmedText').value=words.map(w=>w.text).join(' ');wordIndex=words.length?0:-1;changed();renderUnplaced();updateWordLabel();}
$('alignmentFile').onchange=async e=>{try{const f=e.target.files[0];if(!f)return;if(f.size>2*1024**2)throw new Error('Use an alignment JSON under 2 MiB.');const data=JSON.parse(await f.text());let list=data.words||data;if(data.tiers?.words?.entries)list=data.tiers.words.entries.map(([start,end,text])=>({text,start,end}));if(!Array.isArray(list))throw new Error('Expected words with text, start_s and end_s.');await applyAlignment(list,data.timebase||(data.tiers?'audio':'radar'),data.tiers||data.source==='forced_alignment'?'forced_alignment':'alignment_import');notice('Imported word intervals are pending review.');}catch(e){notice(e.message,true);}};
act('suggestWords',async()=>{if(!selected?.media)return;const take=selected;$('suggestWords').disabled=true;try{const result=await bridge('speechAlign',{sid:take.session_id,tid:take.id});if(selected?.id!==take.id)return;selected.asr_raw_text=result.text;changed();await applyAlignment(result.words,'audio','speech_estimate');notice('Speech word estimates added. Correct the text and boundaries before verifying.');}finally{$('suggestWords').disabled=!native||!selected?.media||selected.articulation==='silent';}});
act('enableShortcut',async()=>{const r=await bridge('enableShortcut',{keyCode:Number($('hotkey').value)});$('hotkeyHelp').textContent=r.message;});$('hotkey').onchange=()=>native&&bridge('setShortcut',{keyCode:Number($('hotkey').value)}).catch(e=>notice(e.message,true));
let polling=false;async function poll(){if(polling)return;polling=true;try{const recovering=state.transport_error;state=await api('live');if(recovering&&$('noticeText').textContent==='Capture engine unavailable. Reopen Gasp if it does not reconnect.')$('notice').hidden=true;$('sourceQuality').textContent=`${sourceName(state.source)} · ${state.profile?profileLabel(state.profile):'Disconnected'}`;$('liveRate').textContent=`${(state.measured_hz||0).toFixed(1)} samples/s`;if(state.error&&state.error!==lastSourceError)notice(state.error,true);lastSourceError=state.error;updateConnection();if(stage==='record')drawLive();}catch(e){state={...state,status:'error',transport_error:true,packet_age_s:null};updateConnection();notice('Capture engine unavailable. Reopen Gasp if it does not reconnect.',true);}finally{polling=false;}}
document.addEventListener('keydown',e=>{const editable=e.target.closest('input,textarea,select,[contenteditable=true]');if(editable)return;if(e.key==='Escape'){if(timelineDrag)cancelTimelineEdit();closeConnectionMenu();if(timedCountdown)countdownCancel=true;else if(busy)releaseRequested=true;wordIndex=-1;wordPlacement=false;if(stage==='replay')drawTimeline();}if(e.key==='Escape'&&activeRecord){api('record/'+activeRecord.id+'/cancel','POST').catch(()=>{});return;}if(dictation||tab!=='capture'||document.querySelector('dialog[open]'))return;if(e.code==='Space'||e.code==='Enter'&&e.target.id==='recordButton'){if(e.target.closest('button,summary')&&e.target.id!=='recordButton'&&!e.target.closest('[data-transcript],[data-word],[data-edge]'))return;e.preventDefault();if(e.repeat)return;if(stage==='replay')play().catch(e=>notice(e.message,true));else if(stage==='record'){if(activeSession?.collection?.plan.task==='reading')toggleRecording().catch(e=>notice(e.message,true));else beginHold();}}if(stage==='replay'&&replay){if(e.key==='['){e.preventDefault();try{setEdge('start_s');}catch(error){notice(error.message,true);}}if(e.key===']'){e.preventDefault();try{setEdge('end_s');}catch(error){notice(error.message,true);}}if(['ArrowLeft','ArrowRight'].includes(e.key)){e.preventDefault();pause();const ts=actualTimes(),dir=e.key==='ArrowLeft'?-1:1;setTime(e.shiftKey?time+dir*.1:ts[Math.max(0,Math.min(ts.length-1,nearest(ts,time)+dir))]);}if((e.metaKey||e.ctrlKey)&&e.key==='z'&&undo.length){e.preventDefault();words=JSON.parse(undo.pop());$('confirmedText').value=words.map(w=>w.text).join(' ');changed();renderUnplaced();updateWordLabel();}}});
document.addEventListener('keyup',e=>{if(['Space','Enter'].includes(e.code)&&hold){e.preventDefault();hold=false;finishTake().catch(e=>notice(e.message,true));}});
async function loadTraining(){return Learning.open();}
async function init(){[decks,profiles]=await Promise.all([api('decks'),api('profiles')]);$('deck').innerHTML=decks.map(d=>`<option value="${d.id}">${esc(d.name)}</option>`).join('')+'<option value="custom-words">My words & short phrases</option><option value="reader">Reader · paste a book or script</option>';let conditions={};try{conditions=JSON.parse(localStorage.getItem('gasp.conditions')||'{}');}catch{}conditionIds.forEach(id=>{if(conditions[id]!==undefined)$(id).value=conditions[id];});deckChanged();sourceChanged();await refreshLibrary();await poll();if(!native){$('enableShortcut').disabled=true;$('hotkeyHelp').textContent='Global shortcut and on-device speech tools are available in the installed app.';}else{const r=await bridge('info');nativeAudioAuthorized=!!r.audioAuthorized;$('hotkey').value=String(r.keyCode);$('hotkeyHelp').textContent=r.shortcutMessage;}await initStudio();if(native)recoverReferenceAudio(true).catch(e=>notice('Audio recovery needs attention: '+e.message,true));setInterval(poll,700);setInterval(readerTick,100);new ResizeObserver(()=>{drawRadar();drawTimeline();updateConnection();if(stage==='record')drawLive();}).observe($('captureLayout'));}
